fn is_happy(s: Vec<char>) -> bool {
    // A happy sequence must have length at least 3.
    if s.len() < 3 {
        return false;
    }

    // Check every contiguous block of 3 characters.
    // If any block has a repeated character, it's not happy.
    for window in s.windows(3) {
        let a = window[0];
        let b = window[1];
        let c = window[2];
        if a == b || a == c || b == c {
            return false;
        }
    }

    // If we never found a bad block, the sequence is happy.
    true
}

